?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ràng buộc tiết giảng – CDS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>
body{background:#edf3f8;font-family:Segoe UI,system-ui,sans-serif;color:#172033}.wrap{max-width:1500px}.hero{background:linear-gradient(110deg,#123f64,#2781ba);color:#fff}.card{border:1px solid #d5e0e8;border-radius:14px}.form-label{font-weight:700}.slot-grid{border-collapse:collapse;width:100%;table-layout:fixed;font-size:.78rem}.slot-grid th,.slot-grid td{border:1px solid #b9c8d2;text-align:center;height:50px;padding:2px}.slot-grid th{background:#e8f0f4}.slot-grid .period{width:76px}.slot-grid td{cursor:pointer;background:#fff;vertical-align:middle}.slot-grid td:hover{background:#e3f1f8}.slot-grid td.has-fixed{background:#eef5ff}.slot-grid td.has-special{background:#fff7e5}.slot-grid td.selected{background:#ccebdc;outline:3px solid #23865d;outline-offset:-3px;font-weight:800}.slot-grid tr.session-start>*{border-top:3px solid #357da1}.slot-mark{display:flex;align-items:center;justify-content:center;gap:4px;max-width:100%;margin:1px;border-radius:5px;padding:2px 4px;font-size:.69rem;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.slot-mark.fixed{background:#dce9ff;color:#174f97;border-left:4px solid #246fc5}.slot-mark.special{background:#ffe8b7;color:#714900;border-left:4px solid #dc9300}.slot-mark i{flex:0 0 auto}.slot-mark span{overflow:hidden;text-overflow:ellipsis}.slot-legend{display:flex;gap:8px;flex-wrap:wrap}.slot-legend .slot-mark{padding:5px 8px;font-size:.75rem}.selected-slot{min-height:38px;border-radius:9px;background:#edf7f1;color:#17613f;padding:.5rem .75rem;font-weight:750}.rule-list{max-height:270px;overflow:auto}.rule-row{display:flex;justify-content:space-between;gap:12px;padding:8px;border-top:1px solid #e1e8ee}.scope-value{display:none}.scope-value.show{display:block}.nav-pills .nav-link{font-weight:750;color:#486174}.nav-pills .nav-link.active{background:#245f82}</style></head><body>
<header class="hero"><div class="container-fluid wrap py-3 d-flex justify-content-between align-items-center"><div><h3 class="mb-0"><i class="bi bi-grid-3x3-gap"></i> Ràng buộc tiết giảng</h3><small>Chọn phạm vi, sau đó click trực tiếp một ô trên bảng tuần</small></div><a class="btn btn-outline-light" href="/tkb_constraints.php">Quay lại ràng buộc</a></div></header>
<main class="container-fluid wrap py-3"><?php show_flash();?><section class="card p-3 mb-3"><div class="d-flex justify-content-between align-items-center gap-2 flex-wrap mb-2"><div><h5 class="mb-0">Bảng chọn vị trí</h5><small class="text-muted">Ô xanh là vị trí đang chọn; dấu ghim cho biết tiết đã được gán cố định.</small><div class="slot-legend mt-2"><span class="slot-mark fixed"><i class="bi bi-pin-angle-fill"></i> Tiết cố định</span><span class="slot-mark special"><i class="bi bi-calendar-x-fill"></i> Tiết nghỉ/hoạt động chung</span></div></div><div class="selected-slot" id="selectedSlot"><i class="bi bi-hand-index"></i> Chưa chọn ô</div></div><div class="table-responsive"><table class="slot-grid"><thead><tr><th class="period">Buổi/tiết</th><?php foreach((array)$data['settings']['days']as$d):?><th><?=$d===8?'Chủ nhật':'Thứ '.$d?></th><?php endforeach;?></tr></thead><tbody><?php foreach(['Sáng'=>(int)$data['settings']['morning_periods'],'Chiều'=>(int)$data['settings']['afternoon_periods']]as$session=>$max):for($p=1;$p<=$max;$p++):?><tr class="<?=$p===1?'session-start':''?>"><th><?=$session?> · <?=$p?></th><?php foreach((array)$data['settings']['days']as$d):$slotKey=ttb_slot_key((int)$d,$session,$p);$slotFixed=(array)($fixedMarks[$slotKey]??[]);$slotSpecial=(array)($specialMarks[$slotKey]??[]);$titles=[];foreach($slotFixed as$subject=>$mark){$markClasses=array_keys((array)$mark['classes']);sort($markClasses,SORT_NATURAL|SORT_FLAG_CASE);$titles[]='Cố định: '.$subject.($markClasses?' ('.implode(', ',$markClasses).')':'');}foreach($slotSpecial as$mark)$titles[]=$mark['label'].' · '.$mark['scope'];?><td class="<?=$slotFixed?'has-fixed ':''?><?=$slotSpecial?'has-special':''?>" data-day="<?=$d?>" data-session="<?=e($session)?>" data-period="<?=$p?>" title="<?=e($titles?implode("\n",$titles):'Click để chọn')?>"><?php $shown=0;foreach($slotFixed as$subject=>$mark):if($shown++>=2)break;$markClasses=array_keys((array)$mark['classes']);sort($markClasses,SORT_NATURAL|SORT_FLAG_CASE);$where=count($markClasses)>2?count($markClasses).' lớp':implode(', ',$markClasses);?><span class="slot-mark fixed"><i class="bi bi-pin-angle-fill"></i><span><?=e($subject.($where?' · '.$where:''))?></span></span><?php endforeach;if(count($slotFixed)>2):?><span class="slot-mark fixed">+<?=count($slotFixed)-2?> tiết cố định</span><?php endif;foreach(array_slice($slotSpecial,0,1)as$mark):?><span class="slot-mark special"><i class="bi bi-calendar-x-fill"></i><span><?=e($mark['label'].' · '.$mark['scope'])?></span></span><?php endforeach;if(count($slotSpecial)>1):?><span class="slot-mark special">+<?=count($slotSpecial)-1?> nội dung</span><?php endif;?></td><?php endforeach;?></tr><?php endfor;endforeach;?></tbody></table></div></section>
