ss="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div><?php endforeach;if(!$data['fixed_lessons']):?><div class="text-muted small">Chưa có tiết cố định.</div><?php endif;?></div></div></div></div></section>
<section class="tab-pane fade" id="specialPanel"><div class="row g-3"><div class="col-lg-7"><div class="card p-3"><h5>Gắn tiết nghỉ hoặc nội dung chung</h5><p class="small text-muted">Ô này sẽ bị khóa. Có thể nhập “Sinh hoạt chuyên môn”, “Chào cờ”, “Nghỉ”…</p><form method="post" action="/tkb_xep.php" class="row g-2 slot-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="special_slot_save"><input type="hidden" class="slot-day" name="day"><input type="hidden" class="slot-session" name="session"><input type="hidden" class="slot-period" name="period"><?php tlc_scope_fields($grades,$classes);?><div class="col-md-5"><label class="form-label">Nội dung hiển thị</label><input class="form-control" name="label" maxlength="120" placeholder="Ví dụ: Sinh hoạt chuyên môn" required></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-success w-100 slot-submit" disabled><i class="bi bi-calendar-x"></i> Khóa ô đã chọn</button></div></form></div></div><div class="col-lg-5"><div class="card p-3 h-100"><h5>Tiết nghỉ/hoạt động đã gắn</h5><div class="rule-list"><?php foreach((array)$data['special_slots']as$r):?><div class="rule-row"><span><strong><?=e($r['label'])?></strong><small class="d-block text-muted"><?=e(tlc_scope_label((string)$r['scope'],(string)$r['value']))?> · <?=((int)$r['day']===8?'Chủ nhật':'Thứ '.e($r['day']))?> · <?=e($r['session'])?> tiết <?=e($r['period'])?></small></span><form method="post" action="/tkb_xep.php"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="special_slot_delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div><?php endforeach;if(!$data['special_slots']):?><div class="text-muted small">Chưa có tiết nghỉ hoặc hoạt động chung.</div><?php endif;?></div></div></div></div></section>
<section class="tab-pane fade" id="doublePanel"><div class="card p-3"><h5>Hai tiết dạy liền nhau</h5><p class="small text-muted">Mỗi cặp luôn cùng ngày, cùng buổi và ở hai tiết liên tiếp.</p><form method="post" action="/tkb_xep.php" class="row g-2"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="double_lesson_save"><div class="col-md-8"><label class="form-label">Môn – lớp – giáo viên</label><select class="form-select" name="assignment_id" required><option value="">Chọn phân công…</option><?php foreach($assignments as$a):if((float)$a['periods']<2)continue;?><option value="<?=e($a['id'])?>"><?=e($a['class'].' · '.$a['subject'].' · '.$a['teacher'].' ('.$a['periods'].' tiết)')?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Số cặp/tuần</label><input class="form-control" type="number" name="pairs" min="1" max="5" value="1"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-success w-100"><i class="bi bi-link"></i> Lưu</button></div></form><div class="rule-list mt-3"><?php foreach((array)$data['double_lessons']as$r):?><div class="rule-row"><span><strong><?=e($r['class'].' · '.$r['subject'])?></strong><small class="d-block text-muted"><?=e($r['teacher'])?> · <?=e($r['pairs'])?> cặp/tuần</small></span><form method="post" action="/tkb_xep.php"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="double_lesson_delete"><input type="hidden" name="assignment_id" value="<?=e($r['assignment_id'])?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div><?php endforeach;if(!$data['double_lessons']):?><div class="text-muted small">Chưa có môn yêu cầu hai tiết liền nhau.</div><?php endif;?></div></div></section></div>
