var selectedSlot=null;document.querySelectorAll('.slot-grid td').forEach(function(cell){cell.addEventListener('click',function(){document.querySelectorAll('.slot-grid td.selected').forEach(function(x){x.classList.remove('selected')});this.classList.add('selected');selectedSlot={day:this.dataset.day,session:this.dataset.session,period:this.dataset.period};document.getElementById('selectedSlot').innerHTML='<i class="bi bi-check-circle"></i> '+(Number(selectedSlot.day)===8?'Chủ nhật':'Thứ '+selectedSlot.day)+' · '+selectedSlot.session+' · Tiết '+selectedSlot.period;document.querySelectorAll('.slot-form').forEach(function(form){form.querySelector('.slot-day').value=selectedSlot.day;form.querySelector('.slot-session').value=selectedSlot.session;form.querySelector('.slot-period').value=selectedSlot.period;form.querySelector('.slot-submit').disabled=false})})});
function updateScope(select){var form=select.closest('form'),scope=select.value;form.querySelectorAll('.scope-value').forEach(function(x){x.classList.remove('show');var child=x.querySelector('[data-scope-name]');if(child)child.removeAttribute('name')});if(scope!=='school'){var box=form.querySelector('.'+scope+'-value');box.classList.add('show');box.querySelector('[data-scope-name]').name='scope_value'}}document.querySelectorAll('.scope-select').forEach(function(select){updateScope(select);select.addEventListener('change',function(){updateScope(this)})});document.querySelectorAll('.slot-form').forEach(function(form){form.addEventListener('submit',function(ev){if(!selectedSlot){ev.preventDefault();alert('Hãy click một ô trên bảng TKB trước khi lưu.')}})});
</script></body></html>
<?php function tlc_scope_fields(array$grades,array$classes):void{?><div class="col-md-4"><label class="form-label">Phạm vi</label><select class="form-select scope-select" name="scope"><option value="school">Toàn trường</option><option value="grade">Theo khối</option><option value="class">Theo lớp</option></select></div><div class="col-md-4 scope-value grade-value"><label class="form-label">Khối</label><select class="form-select" data-scope-name="scope_value"><?php foreach($grades as$g):?><option value="<?=e($g)?>">Khối <?=e($g)?></option><?php endforeach;?></select></div><div class="col-md-4 scope-value class-value"><label class="form-label">Lớp</label><select class="form-select" data-scope-name="scope_value"><?php foreach($classes as$c):?><option><?=e($c)?></option><?php endforeach;?></select></div><?php }
